'use strict';
(function(root){
const key='walk-measurements-v1',esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function breakdown(p){
 let trace;try{trace=root.Measurement36.explain(p);}catch{return '<p>保存された条件では計算過程を再構成できません。現在の式で再計算してください。</p>';}if(!trace)return '';
 const number=v=>Number(v).toLocaleString('ja-JP',{maximumFractionDigits:6});
 const names={slash:'斬体＋補助',element:'属性',race:'系統',name:'固有敵特効',typeResistance:'種類耐性',elementResistance:'属性耐性',elementDebuff:'属性弱化',criticalMin:'会心・下側',criticalMax:'会心・上側',criticalBoost:'会心ダメージ補助',charge:'ため',dual:'二刀',damageTakenGroup:'凍結＋斬体被ダメージ補正（合成）',freeze:'凍結',typeDebuff:'被ダメージ増加',causality:'因果',skill:'スキル倍率'};
 const stages=(label,row)=>'<p>'+label+'：基礎乱数値 '+number(row.base)+' → 補正・会心後 '+number(row.first)+' → 固有技補正・ため後 '+number(row.second)+' → 二刀補正後 '+number(row.third)+'</p>';
 return '<details><summary>物理1発の計算過程と装備を確認</summary><p>'+esc(trace.scope)+'</p><p>補正後攻撃力 '+number(trace.effectiveAttack)+'／計算に使う守備力 '+number(trace.effectiveDefense)+'</p><p>'+Object.entries(trace.factors).filter(([key])=>trace.factors.damageTakenGroup==null||!['freeze','typeDebuff'].includes(key)).map(([key,value])=>esc(names[key]||key)+' ×'+number(value)).join(' ／ ')+'</p>'+stages('最初の1発・下側',trace.first.stages.min)+stages('最初の1発・上側',trace.first.stages.max)+'<p>2発目以降（ため消費後）：'+number(trace.subsequent.min)+'〜'+number(trace.subsequent.max)+'</p><p>装備：'+esc((p.equipment||[]).map(x=>x.label).join(' / ')||'旧記録のため未保存')+'</p><p>こころ：'+esc((p.hearts||[]).map(x=>x.name).join(' / ')||'未装備または旧記録')+'</p><p>この内訳は会心ガード等を適用する前の1発です。行動合計や画面の最終ダメージとは分けて確認してください。</p></details>';
}
function mount({target,result,configuration,profile,master}){
 configuration=JSON.parse(JSON.stringify(configuration));profile=JSON.parse(JSON.stringify(profile));let records=[];try{records=JSON.parse(localStorage.getItem(key)||'[]');if(!Array.isArray(records))records=[];}catch{}records=records.slice(-30);
 const choices=[];for(const l of result.logs.filter(l=>l.damage)){choices.push({order:l.order,cast:null,label:l.order+'番 キャラ'+(l.actor+1)+' '+l.name+'（行動の攻撃合計）'});for(const [n,d]of (l.damage.casts||[]).entries())choices.push({order:l.order,cast:n,label:l.order+'番 '+(n+1)+'発目 '+d.kind+'（詠唱・やまびこ1回分）'});}
 target.innerHTML='<details class="panel"><summary>実測ダメージと照合・記録</summary><p>選んだ行動合計または詠唱1回分と、同じ範囲の実機表示を比べます。多段技は全ヒット分を合計してください。やまびこ・連続呪文を含むかも合わせます。計算条件も保存します。</p><label>照合する攻撃<select id="measure-action">'+choices.map((x,i)=>'<option value="'+i+'">'+esc(x.label)+'</option>').join('')+'</select></label><label>値の種類<select id="measure-kind"><option value="measured">実機で確認した値</option><option value="expectation">目安・期待値（実測に含めない）</option></select></label><label>ダメージ（複数回は空白・カンマ区切り）<input id="measure-values" inputmode="numeric" placeholder="例：123456, 125000"></label><label>メモ・出典<input id="measure-note" maxlength="500" placeholder="実測時の条件や記事URL"></label><button type="button" id="measure-save" '+(choices.length?'':'disabled')+'>条件と一緒に保存して比較</button><button type="button" id="measure-export">照合記録をJSON保存</button><p id="measure-status" role="status"></p><div id="measure-records"></div><p class="muted">最大30件をこのブラウザに保存します。範囲内でも式の正しさの証明にはなりません。暴走・超暴走は代表倍率で、表示範囲は実測乱数の上下限ではありません。記録から倍率を自動補正することはありません。</p></details>';
 const $=s=>target.querySelector(s),status=$('#measure-status');
 function report(r,p=r.predicted,c=r.comparison){return '<strong>'+esc(r.kind==='measured'?'実測':'期待値')+'</strong> '+esc(p.name)+'：記録 '+c.minObserved.toLocaleString()+'〜'+c.maxObserved.toLocaleString()+' / 計算 '+p.min.toLocaleString()+'〜'+p.max.toLocaleString()+'<br>平均と計算中央の差 '+Math.round(c.difference).toLocaleString()+'（'+(c.differencePercent==null?'比較不可':c.differencePercent.toFixed(1)+'%')+'）・表示範囲外 '+c.outside+'/'+c.count+'件'+(p.referenceOnly||p.conditional?' ／ 条件付き・代表値比較':'')+'<br>'+esc(c.status==='within-modeled-range'?'計算範囲内（正確性の証明ではない）':c.status==='outside-modeled-range'?'計算範囲外：条件または式の差を確認':'照合保留：未確認条件あり')+(c.unresolved?.length?'<ul>'+c.unresolved.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'');}
 function draw(){const host=$('#measure-records');host.innerHTML=records.map((r,i)=>'<article class="record-card"><p>'+report(r)+'</p>'+breakdown(r.predicted)+'<p>'+esc(r.created)+' · 保存時モデル '+esc(r.model)+'</p><p>'+esc(r.note)+'</p><button type="button" data-recheck="'+i+'">保存条件を現在の式で再計算</button><button type="button" data-remove="'+i+'">この記録を削除</button><p id="measure-recheck-'+i+'"></p></article>').join('')||'<p>照合記録はまだありません。</p>';host.querySelectorAll('[data-recheck]').forEach(b=>b.onclick=()=>{try{const i=Number(b.dataset.recheck),r=records[i],v=root.Measurement36.recompute(r,master);$('#measure-recheck-'+i).innerHTML='現在の式：'+report(r,v.predicted,v.comparison)+breakdown(v.predicted);}catch(e){status.textContent=e.message;}});host.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const next=records.filter((_,i)=>i!==Number(b.dataset.remove));try{localStorage.setItem(key,JSON.stringify(next));records=next;draw();status.textContent='記録を削除しました。';}catch{status.textContent='保存できませんでした。';}});}
 $('#measure-save').onclick=()=>{try{const raw=$('#measure-values').value.trim();if(!raw||!/^\d+(?:[\s,、]+\d+)*$/.test(raw))throw Error('ダメージを整数で入力してください');const choice=choices[Number($('#measure-action').value)];if(!choice)throw Error('攻撃を選んでください');const record=root.Measurement36.create({result,configuration,profile,...choice,observations:raw.split(/[\s,、]+/).map(Number),kind:$('#measure-kind').value,note:$('#measure-note').value}),next=[...records,record].slice(-30);localStorage.setItem(key,JSON.stringify(next));records=next;draw();status.textContent='装備・行動順・補正と照合値を保存しました。';}catch(e){status.textContent=e.message;}};
 $('#measure-export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({schema:1,records},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='walk-measurements.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};draw();
}
root.MeasurementUI36={mount};
})(typeof window==='undefined'?globalThis:window);
